15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 */
19	@Profile("harness")
20	@RestController
21	@RequestMapping("/__test__")
22	public class TestSupportController {
23	
24	    private final Audit audit;
25	    private final JdbcTemplate jdbc;
26	
27	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
28	        this.audit = audit;
29	        this.jdbc = jdbc;
30	    }
31	
32	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
33	    @PostMapping("/reset")
34	    public void reset() {
35	        audit.clear();
36	        // Disable FK checks so a referenced parent (clients) can be truncated alongside its child.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE line_items RESTART IDENTITY");
39	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
